    "tour.welcome.title": "Welcome to Bee Flow",
    "tour.welcome.body": "Let's take a quick tour of the basics — under a minute. You can skip or replay it anytime.",
    "tour.chat.title": "Chat with AI",
    "tour.chat.body": "Start here. Ask a question, draft an email, or brainstorm — “New Chat” opens a fresh conversation whenever you need one.",
    "tour.agents_editor.title": "Build your own agents",
    "tour.agents_editor.body": "Studio is where you create and fine-tune AI agents for the way your team works.",
    "tour.marketplace.title": "Discover agents",
    "tour.marketplace.body": "Browse ready-made agents your team has shared, then pick one to start chatting right away.",
    "tour.knowledge.title": "Add your knowledge",
    "tour.knowledge.body": "Give your agents your own documents and data with a knowledge base — then they can answer using your content.",
