    "tour.account.body": "Open your account menu here for settings, appearance, and to sign out.",
    "tour.preferences.title": "Make it yours",
    "tour.preferences.body": "Tune your defaults — language, model, and more — in Preferences.",
    "tour.create_intro.title": "Create your first agent",
    "tour.create_intro.body": "Bee Flow can build a custom agent from a plain-English description. Want to try it now? You can skip and do this later.",
