    "compliance.checks.iso_mail_security.title": "Mail spoofing protection",
    "compliance.checks.iso_mail_security.desc": "Your sending domain must publish SPF, an enforcing DMARC policy and DKIM keys — without them anyone can send mail that looks like it comes from your organisation.",
    "compliance.checks.iso_mail_security.fix": "Enable the mail-security connector under ISO 27001 → Connectors, set your domain, and add the missing DNS records at your DNS provider.",
    "compliance.checks.iso_tls_endpoints.title": "TLS on public endpoints",
    "compliance.checks.iso_tls_endpoints.desc": "Public endpoints must serve valid certificates over TLS 1.2 or newer, renewed well before expiry — an expired certificate is an outage and an audit finding at once.",
    "compliance.checks.iso_tls_endpoints.fix": "Enable the TLS connector under ISO 27001 → Connectors, list your public endpoints, and renew any certificate the check flags.",
    "compliance.connector.mail_security.title": "Mail security (SPF/DKIM/DMARC)",
    "compliance.connector.mail_security.desc": "Credential-less DNS probe of your sending domain — proves spoofing protection for A.5.14.",
    "compliance.connector.tls_endpoints.title": "TLS certificates",
    "compliance.connector.tls_endpoints.desc": "Credential-less handshake against your public endpoints — proves certificate hygiene for A.8.24.",
